import{A as e,B as t,D as n,K as r,L as i,N as a,j as o,p as s}from"./chunk-JyOHs9Cd.js";var c={class:`min-h-screen px-4 pt-4 pb-40`},l={class:`max-w-[65rem] mx-auto`},u={__name:`HelpView`,setup(u){let d=s();return(s,u)=>{let f=t(`van-icon`);return i(),e(`div`,c,[n(`div`,l,[n(`button`,{class:`flex items-center gap-2 text-slate-400 hover:text-slate-100 transition-colors mb-4`,onClick:u[0]||=e=>r(d).push(`/`)},[a(f,{name:`arrow-left`,size:`20`,"aria-hidden":`true`}),u[1]||=n(`span`,{class:`text-sm font-medium`},`На главную`,-1)]),u[2]||=o(`<h1 class="text-2xl font-bold text-slate-100 mb-1">Как пользоваться</h1><p class="text-sm text-slate-400 mb-5"> Короткая инструкция для новых пользователей приложения «Учёт брака». </p><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">🏁</span> Первые шаги </h2><ul class="text-sm text-slate-300 leading-relaxed list-disc pl-5 space-y-1.5"><li> Приложение работает на одном устройстве: все данные хранятся в браузере и интернет не нужен. </li><li> При первом запуске задайте магазин — номер (3 цифры) и текст пломбы. Это в «Настройках» (шестерёнка в правом верхнем углу). </li><li>На главной загрузите Excel-файл (.xlsx) со списком брака — это справочная база.</li><li>Дальше перемещайтесь по приложению через меню внизу экрана.</li></ul></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">📦</span> Миксы </h2><ul class="text-sm text-slate-300 leading-relaxed list-disc pl-5 space-y-1.5"><li> Вкладка «Миксы»: создайте короб и сканируйте в него товары — через ТСД или камеру телефона. </li><li>В поле ввода достаточно номера товара — префикс магазина добавится сам.</li><li> В подсказках у товара сразу видно, где он уже лежит: «М7» (микс), «М7 → П3» (микс на паллете), «П3» (паллета), «В» (отдельные). Повторы приложение не даёт добавить. </li><li>Кнопка «Отменить» убирает последние действия — до 50 шагов.</li><li>Завершённые коробы попадают во вкладку «Результаты».</li></ul></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">🔀</span> Отдельные </h2><p class="text-sm text-slate-300 leading-relaxed"> Брак, который не кладут в короб: сканируйте его во вкладку «Отдельные». В поиске такие товары помечаются «В». </p></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">🟨</span> Паллеты </h2><p class="text-sm text-slate-300 leading-relaxed"> Вкладка «Паллеты»: ставьте готовые миксы на паллету или кладите товары прямо в паллету («П»). Готовую паллету можно экспортировать в Excel. </p></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">📋</span> Результаты </h2><p class="text-sm text-slate-300 leading-relaxed"> Здесь лежат завершённые миксы и паллеты. Каждый можно открыть и выгрузить в Excel — в файле будет пломба вашего магазина. </p></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">🔎</span> Поиск </h2><p class="text-sm text-slate-300 leading-relaxed"> Ищите товар по номеру, названию или артикулу — поиск покажет, в каком контейнере он лежит. Можно искать по месту: наберите «М6», «П12» или «В», и увидите всё содержимое этого места. </p></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">🗂</span> База данных </h2><p class="text-sm text-slate-300 leading-relaxed"> Вкладка «База данных» — просмотр загруженного Excel: поиск по любому полю и по месту хранения. Новая загрузка файла заменяет базу целиком. </p></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">⚙️</span> Настройки </h2><ul class="text-sm text-slate-300 leading-relaxed list-disc pl-5 space-y-1.5"><li>«Магазин» — сменить номер и пломбу (осторожно: данные будут очищены).</li><li>«Резервная копия» — сохранить все данные в файл и восстановить их на устройстве.</li><li>«Импорт» — загрузить ранее выгруженные миксы или паллеты.</li><li>«Очистка данных» — полный сброс. Используйте только если уверены.</li></ul></section><section class="bg-slate-800/50 border border-slate-700 rounded-2xl p-4 mb-3"><h2 class="flex items-center gap-2 text-base font-semibold text-slate-100 mb-2"><span aria-hidden="true">📱</span> Если сканируете ТСД </h2><ul class="text-sm text-slate-300 leading-relaxed list-disc pl-5 space-y-1.5"><li> ТСД работает как клавиатура: код попадает в активное поле «Скан ТСД». Держите его в фокусе — тогда сканер сразу ловит товар. </li><li> Повреждённый штрихкод приложение отклонит с предупреждением — пересканируйте или введите номер вручную. </li></ul></section><p class="text-xs text-slate-500 italic mt-4"> Если что-то из этого не получается — спросите у того, кто вам дал приложение. </p>`,12)])])}}};export{u as default};